    if (str == null || suffix == null) {
        return false;
    }
    int strLength = str.length();
    int suffixLength = suffix.length();
    if (suffixLength > strLength) {
        return false;
    }
    if (suffixLength == 0) {
        return true;
    }
    if (ignoreCase) {
        return str.regionMatches(strLength - suffixLength, suffix, suffixLength, suffixLength);
    } else {
        return str.endsWith(suffix);
    }
}

