public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 2) return 2;

    int boundary = (int) Math.sqrt(desiredCapacity);

    while (true) {
        for (int i = 2; i <= boundary; i++) {
            if (desiredCapacity % i == 0) {
                desiredCapacity += 1;
                break;
            }
        }

        // Check everything up to 10% above desiredCapacity if it's at least 1000
        if (desiredCapacity >= 1000 && ((desiredCapacity * 11) / 100) < boundary) {
            break;
        }
    }

    return desiredCapacity;
}

