        return null;
    }
    StringBuffer sb = new StringBuffer();
    for (int i = 0; i < str.length(); i++) {
        char ch = str.charAt(i);
        if (ch == '\\') {
            if (i + 1 < str.length()) {
                char next = str.charAt(i + 1);
                if (next == 'n') {
                    sb.append('\n');
                    i++; // Skip the next character
                } else if (next == 't') {
                    sb.append('\t');
                    i++; // Skip the next character
                } else if (next == '\\' || next == '"') {
                    sb.append(next);
                    i++; // Skip the next character
                } else {
                    // Unknown escape sequence, escape the backslash itself
                    sb.append("\\");
                    sb.append(next);
                }
            } else {
                // Null character after \\, so just escape it
                sb.append("\\");
            }
        } else {
            sb.append(ch);
        }
    }
    return sb.toString();
}

