public static String applyRelativePath(String path, String relativePath) {
    String[] pathComponents = path.split("/");
    String[] relativeComponents = relativePath.split("/");
    int minLength = Math.min(pathComponents.length, relativeComponents.length);

    for (int i = 0; i < minLength; i++) {
        if (relativeComponents[i].equals("..")) {
            if (i == 0) {
                return pathComponents[i];
            } else {
                StringBuilder result = new StringBuilder();
                for (int j = 0; j < i - 1; j++) {
                    result.append(pathComponents[j]).append("/");
                }
                return result.toString();
            }
        } else if (!relativeComponents[i].isEmpty()) {
            pathComponents[i] = relativeComponents[i];
        }
    }

    StringBuilder result = new StringBuilder();
    for (int j = 0; j < pathComponents.length; j++) {
        if (!pathComponents[j].isEmpty()) {
            result.append(pathComponents[j]);
            result.append("/");
        }
    }
    return result.toString().substring(0, result.toString().length() - 1);
}

