    if (firstByte == -1) {
        return 0;
    }

    bytecodeOffset = Byte.toUnsignedInt(firstByte) & 0x7F;

    tag = bytecodeOffset << 7;
    firstByte = readByte();
    if (firstByte != -1) {
        tag |= Byte.toUnsignedInt(firstByte) & 0x7F;
    }

    return tag;
}

